css:
*{box-sizing:border-box}body{margin:0;font-family:"Apple SD Gothic Neo","Malgun Gothic","Noto Sans KR",sans-serif;font-size:13px;color:#222;background:#eef1f4}
.top{background:#1f3a5f;color:#fff;padding:10px 20px;display:flex;justify-content:space-between;align-items:center}
.top .sys{font-weight:700;letter-spacing:.02em}.top .user{font-size:12px;opacity:.85}
.crumb{background:#fff;border-bottom:1px solid #d5dbe2;padding:8px 20px;font-size:12px;color:#556}
.wrap{max-width:1280px;margin:16px auto;padding:0 16px}
h1{font-size:20px;margin:6px 0 12px}h2{font-size:15px;margin:22px 0 8px;padding-left:8px;border-left:4px solid #1f3a5f}
h3{font-size:13px;margin:14px 0 6px;color:#1f3a5f}
.bar{background:#fff;border:1px solid #d5dbe2;border-radius:4px;padding:10px 14px;display:flex;gap:14px;flex-wrap:wrap;align-items:center;font-size:12px}
.bar label{color:#556}.bar input,.bar select{border:1px solid #c8cfd8;border-radius:3px;padding:3px 6px;font-size:12px;background:#fafbfc}
.bar .btn{background:#1f3a5f;color:#fff;border:0;border-radius:3px;padding:5px 12px}
.card{background:#fff;border:1px solid #d5dbe2;border-radius:4px;padding:14px 16px;margin-top:12px}
p{margin:6px 0;line-height:1.55;color:#333}blockquote{margin:8px 0;padding:8px 12px;border-left:3px solid #9fb3c8;background:#f6f8fa;color:#334}
pre{background:#f6f8fa;border:1px solid #e1e5ea;padding:8px 10px;font-size:12px;overflow:auto}
table.tbl{border-collapse:collapse;width:100%;margin:8px 0 10px;font-size:12px}
table.tbl th{background:#f0f3f7;border:1px solid #d5dbe2;padding:6px 8px;text-align:left;white-space:nowrap;position:sticky;top:0}
table.tbl td{border:1px solid #e1e5ea;padding:5px 8px;vertical-align:top;line-height:1.45}
table.tbl tbody tr:nth-child(even){background:#fafbfc}
.meta{color:#667;font-size:12px}.foot{color:#889;font-size:11px;text-align:center;padding:24px 0}
@media print{body{background:white}.top,.crumb,.bar{display:none}.wrap{max-width:none;margin:0;padding:0}.card{border:0;break-inside:auto}table.tbl th{position:static}tr{break-inside:avoid}.foot{padding:8px}}
ul{margin:6px 0 6px 18px;padding:0}li{margin:3px 0;line-height:1.5}
